import{_ as r,l as i,o as e,c as s,v as t,p as d,x as n,d as l,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"依值类型直觉","description":"","frontmatter":{"title":"依值类型直觉","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dependent-types-intuition.md","filePath":"cs/dependent-types-intuition.md","lastUpdated":1789023840000}'),h={name:"cs/dependent-types-intuition.md"};function u(m,a,_,f,T,A){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="依值类型直觉" tabindex="-1">依值类型直觉 <a class="header-anchor" href="#依值类型直觉" aria-label="Permalink to &quot;依值类型直觉&quot;">​</a></h1><div class="epigraph"><p>类型可以提到值：长度为 $n$ 的向量、等于证明。判断仍是 $\\Gamma\\vdash t:\\tau$，但 $\\tau$ 里有项。核检查，人不手写全部归约。</p><footer>—— 据 Martin-Löf 类型论；Pierce TAPL 对依值类型的导引；[证明助手](/cs/proof-assistants)课的延续整理</footer></div><p>上一课<a href="/cs/exhaustiveness-check">穷尽性</a>在闭 ADT 上找反例。缺口是更强的索引：<code>Vec A n</code> 的 <code>cons</code> 把 \\(n\\) 变成 \\(n+1\\)，匹配 <code>nil</code> 时 \\(n\\) 必须是 \\(0\\)。计算理论补层的<a href="/cs/proof-assistants">证明助手</a>已给 Curry–Howard 直觉；本课从<strong>编程语言类型系统</strong>再接一次：依值如何改变检查算法，而不是再讲 tactic。不重写 STLC 的箭头规则，只加 Π。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>HM 的 \\(\\forall\\alpha\\) 量化类型，不量化自然数项。依值：\\(\\Pi n:\\mathbb{N}.\\,\\mathrm{Vec}\\,A\\,n \\to \\ldots\\)。应用时 \\(n\\) 是项，须比较类型时做定义等式（\\(1+1 = 2\\)）。缺口是<strong>类型里的计算</strong>，不是宏展开。</p><p>可判定性：若允许任意递归函数出现在类型里，相等不可判定。助手限制终止；语言（Idris、Lean 作 PL）同样要终止或推迟。</p><h3 id="依值不是「运行时把类型当值随便改」" tabindex="-1">依值不是「运行时把类型当值随便改」 <a class="header-anchor" href="#依值不是「运行时把类型当值随便改」" aria-label="Permalink to &quot;依值不是「运行时把类型当值随便改」&quot;">​</a></h3><p>阶段仍可擦除证明部分。运行时不必留下 \\(n\\) 的证明项。与渐进类型的 <code>Any</code> 不同：这里多的是静态等式，不是动态 tag。</p><p><span class="marginnote">Martin-Löf。Howard。The Univalent Foundations Program 的 HoTT 书不在本课展开。Pierce 有依值导引。本课不进宇宙层级细节，证明助手课已点名。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>核心：Π、Σ、归纳族。检查：转换规则——若 \\(t:A\\) 且 \\(A\\equiv B\\) 则 \\(t:B\\)。实现：规范化类型再比（或用等价算法）。编程：长度索引的 <code>append</code> 类型里写出加法。</p>',11)),(e(),d(p,null,{default:n(()=>[c(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20TM%5B%22%E9%A1%B9%22%5D%20--%3E%20TY%5B%22%E5%8F%AF%E4%BE%9D%E5%80%BC%E7%9A%84%E7%B1%BB%E5%9E%8B%22%5D%0A%20%20TY%20--%3E%20EQ%5B%22%E5%AE%9A%E4%B9%89%E7%9B%B8%E7%AD%89%22%5D%0A%20%20EQ%20--%3E%20KER%5B%22%E6%A0%B8%E6%A3%80%E6%9F%A5%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与<a href="/cs/hindley-milner-w">算法 W</a>：依值推断一般不可全自动，故双向检查（合成/检验）是实用算法，点名。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>抽取：证明擦掉，剩下计算。与 STLC 规范化对照：依值语言若允许非终止，逻辑可塌；作 PL 用时人选择是否要逻辑一致性。</p><p>不要把 <code>Vec</code> 当运行时每次检查长度的列表包装还称为依值；那是断言，不是 Π。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 CIC 全部规则。后课默认：类型可依赖值；相等要计算。下一课线性类型：另一轴——用几次，而不是依赖哪个 \\(n\\)。</p><p>也不把 TypeScript 的条件类型当 Martin-Löf。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>依值：Π 让类型提到项；检查含定义相等。</li><li>终止限制换可判定核。</li><li>与 HM 量化、与动态 tag 都不同。</li><li>出处：Martin-Löf；Howard；Pierce TAPL；对照证明助手课。</li></ul>',9))])}const B=r(h,[["render",u]]);export{P as __pageData,B as default};
